'use strict';
// Synthetic protection flow only. No identity provider, messages or account API.
function staffSecurity(){return management.security||(management.security={open:false,reason:'',review:null,proof:null,operation:null,records:{},outcome:'confirmed',auth:'success',error:null});}
function securityError(ru,en){staffSecurity().error=[ru,en];return false;}
const securityBusy=()=>['pending','unknown'].includes(staffSecurity().operation?.status);
const securityTarget=id=>managementStaff.find(s=>s[0]===id);
function securityCanBlock(id){return !!managementAccess().security&&!!securityTarget(id)&&id!==actor().id&&securityTarget(id)[3]!=='owner'&&managementAssignment(id).status!=='blocked';}
function securityReview(){const s=staffSecurity(),id=management.staff;s.error=null;s.proof=null;s.review=null;if(!securityCanBlock(id)||securityBusy()||managementBusy()||s.reason.trim().length<8||s.reason.length>500)return securityError('Укажите причину (8–500 символов). Нужны права владельца и завершённая предыдущая операция.','Enter a reason (8–500 characters). Owner access and a resolved previous operation are required.');s.review={staff:id,actor:actor().id,revision:managementAssignment(id).revision,reason:s.reason.trim()};return true;}
function securityReviewValid(){const s=staffSecurity(),d=s.review;return !!d&&securityCanBlock(d.staff)&&d.staff===management.staff&&d.actor===actor().id&&d.revision===managementAssignment(d.staff).revision&&d.reason===s.reason.trim()&&!management.stale&&!securityBusy()&&!managementBusy();}
function securityAuthenticate(){const s=staffSecurity();s.proof=null;if(!securityReviewValid()||s.auth!=='success'||!account.protected)return securityError('Проверка ключом не завершена или данные изменились. Повторите проверку без отправки команды.','Key verification did not finish or the data changed. Review again before submitting.');s.proof=managementDigest(s.review);return true;}
function securitySubmit(){const s=staffSecurity();if(!securityReviewValid()||s.proof!==managementDigest(s.review))return securityError('Нужна свежая проверка физическим ключом для этого сотрудника, причины и версии.','A fresh physical-key check must match this employee, reason and revision.');const d=structuredClone(s.review),id='SEC-DEMO-'+(management.events.length+1);s.operation={id,payload:d,status:'pending',applied:false};s.proof=null;s.review=null;managementLog(['Защита аккаунта: команда принята','Account protection: command accepted'],d.staff,null,{operation:id,reason:d.reason},'pending');s.records[d.staff]={operation:id,incident:'INC-'+id,blocked:false,recovery:false,operationObject:s.operation};incidents.records.push({id:'INC-'+id,staffSecurity:d.staff,securityOperation:s.operation,key:'staff-security',uid:'',sid:'',ticket:'',name:securityTarget(d.staff)[1],venue:'Shadow',date:management.clock.slice(0,10),priority:'high',status:'investigating',assignee:actor().id,title:['Подозрение на взлом аккаунта сотрудника','Suspected staff account compromise'],version:1,notes:[],events:[],note:'',resolved:false,evidence:null});return securityResolve();}
function securityResolve(){const s=staffSecurity(),op=s.operation;if(!op||!securityBusy()||!managementAccess().read)return false;const next=s.outcome;if(!['pending','unknown','confirmed','failed'].includes(next))return false;const d=op.payload;if(next==='confirmed'&&(!securityCanBlock(d.staff)||d.actor!==actor().id||d.revision!==managementAssignment(d.staff).revision||management.stale)){op.status='conflict';managementLog(['Защита аккаунта: нужна новая проверка','Account protection: fresh review required'],d.staff,null,{operation:op.id},'conflict');return false;}op.status=next;if(next==='confirmed'&&!op.applied){const before=managementAssignment(d.staff);management.assignments[d.staff]={...before,status:'blocked',revision:before.revision+1};management.sessions[d.staff]='ended';management.approvals[d.staff]='revoked';op.applied=true;s.records[d.staff].blocked=true;managementLog(['Аккаунт заблокирован','Account blocked'],d.staff,before,{status:'blocked',reason:d.reason,revision:before.revision+1});}else managementLog(['Результат защитной команды','Protection command outcome'],d.staff,null,{operation:op.id},next);return true;}
const securityButton=(ru,en,a,extra='',primary=false)=>`<button type="button" class="btn${primary?' primary':''}" data-security="${a}" ${extra}>${mn(ru,en)}</button>`;
function securityEffects(confirmed=false){return `<ul class="management-rights"><li>${mn(confirmed?'Вход и новые действия от имени сотрудника запрещены.':'Закрыть вход и запретить новые действия от имени сотрудника.',confirmed?'Sign-in and new employee actions are blocked.':'Block sign-in and new actions by this employee.')}</li><li>${mn(confirmed?'Все сеансы сотрудника завершены.':'Завершить все сеансы сотрудника.',confirmed?'All employee sessions are ended.':'End all employee sessions.')}</li><li>${mn(confirmed?'Неиспользованные подтверждения выплат и восстановления отозваны.':'Отозвать неиспользованные подтверждения выплат и восстановления.',confirmed?'Unused payout and recovery approvals are revoked.':'Revoke unused payout and recovery approvals.')}</li></ul><p class="support-notice">${mn('Уже отправленные сделки и переводы могут завершиться. Сверка и необходимые резервы сохраняются.','Submitted trades and transfers may still complete. Reconciliation and required reserves remain.')}</p>`;}
function securityPage(){const s=staffSecurity(),id=management.staff,d=s.review,rec=s.records[id],op=rec?.operationObject||null,can=securityCanBlock(id);return `${securityButton('К карточке сотрудника','Back to employee','back')}<h2>${mn('Защита аккаунта сотрудника','Employee account protection')}</h2><p><strong>${escape(managementStaffName(id))}</strong> · ${id} <span class="badge">${managementStatus(managementAssignment(id).status)}</span></p><p>${mn('Вы защищаете чужую учётную запись. Ваш сотрудник и полномочия не меняются.','You are protecting another account. Your signed-in identity and permissions stay the same.')}</p>${s.error?`<p role="alert" class="account-error">${mn(...s.error)}</p>`:''}${rec?.blocked?`<section class="panel"><h3>${mn('Блокировка подтверждена','Block confirmed')}</h3>${securityEffects(true)}</section>`:securityBusy()?`<section class="panel" role="status"><h3>${managementStatus(s.operation.status)}</h3><p>${s.operation.id} · ${s.operation.payload.staff}</p><p>${mn('Блокировка пока не подтверждена. Не считайте аккаунт защищённым и не отправляйте повторную команду.','Blocking is not confirmed. Do not assume the account is protected or send another command.')}</p>${securityButton('Проверить прежнюю команду','Check existing command','check','',true)}</section>`:can?`<section class="panel"><h3>${mn('Что вызвало подозрение','Reason for concern')}</h3><div class="field"><label for="security-reason">${mn('Причина блокировки','Blocking reason')}</label><textarea id="security-reason" rows="3" maxlength="500" placeholder="${mn('Например: сотрудник сообщил о неизвестном входе','For example: employee reported an unfamiliar sign-in')}">${escape(s.reason)}</textarea></div><p class="muted">${mn('Не вставляйте ключи, пароли или коды восстановления.','Do not include keys, passwords or recovery codes.')}</p>${!d?securityButton('Проверить последствия','Review effects','review','',true):''}</section>`:`<p class="support-notice">${mn(securityTarget(id)?.[3]==='owner'?'Блокировка владельца требует отдельной защищённой процедуры. Этот сценарий не меняет доступ владельцев.':'Для блокировки другого сотрудника в этом прототипе нужен владелец. Свой аккаунт защищают через личный профиль.',securityTarget(id)?.[3]==='owner'?'Blocking an owner requires a separate protected procedure. This flow does not change owner access.':'This prototype requires an owner to block another employee. Protect your own account through your personal profile.')}</p>`}${d?`<section class="panel"><h3>${mn('Проверьте последствия','Review the effects')}</h3><p>${d.staff} · ${mn('Версия','Revision')} ${d.revision} · ${escape(d.reason)}</p>${securityEffects()}<p>${mn('Будет создан инцидент. Уведомления обоим владельцам отслеживаются отдельно от блокировки.','An incident will be created. Notifications to both owners are tracked separately from blocking.')}</p>${s.proof?`<p role="status">${mn('Учебная проверка физическим ключом выполнена для этой версии.','Synthetic physical-key check completed for this revision.')}</p>${securityButton('Заблокировать аккаунт','Block account','submit','',true)}`:securityButton('Подтвердить физическим ключом','Verify with physical key','authenticate','',true)} ${securityButton('Отмена','Cancel','cancel')}</section>`:''}${op&&!securityBusy()?`<p role="status">${op.id} · ${managementStatus(op.status)}</p>`:''}${rec?`<section class="panel"><h3>${mn('Следующие действия','Next steps')}</h3><div class="incident-actions">${securityButton('Открыть инцидент','Open incident','incident')}${securityButton('Проверить последние действия','Review recent actions','audit')}${rec.blocked?securityButton('Восстановление доступа','Access recovery','recovery'):''}</div><p>${mn('Уведомления владельцам A и B: учебная очередь, доставка не подтверждена.','Owner A and B notifications: synthetic queue, delivery unconfirmed.')}</p>${rec.recovery?securityRecoveryText():''}</section>`:''}<details class="account-test"><summary>${mn('Учебные состояния — не реальные настройки','Synthetic states — not real settings')}</summary>${managementSelect('security-outcome',mn('Ответ на команду','Command outcome'),['confirmed','pending','unknown','failed'].map(k=>[k,managementStatus(k)]),s.outcome)}${managementSelect('security-auth',mn('Проверка ключом','Key verification'),[['success',mn('Успешно','Success')],['cancelled',mn('Отменена','Cancelled')]],s.auth)}</details>`;}
function securityRecoveryText(){return `<h4>${mn('Восстановление — отдельный процесс','Recovery is a separate process')}</h4><ol><li>${mn('Подтвердить личность по отдельной защищённой процедуре.','Verify identity through a separate protected process.')}</li><li>${mn('Заменить и проверить сильные способы входа.','Replace and verify strong sign-in methods.')}</li><li>${mn('Отдельно проверить актуальные права и решение о возврате доступа.','Separately review current permissions and the decision to restore access.')}</li></ol><p>${mn('Старые сеансы и подтверждения не восстанавливаются. Здесь нет кнопки обхода или автоматической разблокировки.','Old sessions and approvals are not restored. There is no bypass or automatic unblock here.')}</p>`;}
function securityAction(a){const s=staffSecurity();s.error=null;if(!managementAccess().read)return false;if(a==='open'){s.open=true;s.review=null;s.proof=null;s.reason='';}else if(a==='back'){s.open=false;s.review=null;s.proof=null;}else if(a==='review')return securityReview();else if(a==='authenticate')return securityAuthenticate();else if(a==='submit')return securitySubmit();else if(a==='check')return securityResolve();else if(a==='cancel'){s.review=null;s.proof=null;}else if(a==='incident'){const rec=s.records[management.staff];if(!rec)return false;incidents.id=rec.incident;navigate('incident');}else if(a==='return'){navigate('management');s.open=true;}else if(a==='audit'){management.tab='audit';management.auditQuery=management.staff;management.auditResult='all';management.auditFrom='2026-10-17';management.auditTo=management.clock.slice(0,10);s.open=false;navigate('management');management.notice=['Журнал текущего учебного прохода по сотруднику. Исторические входы и действия не загружены; их отсутствие здесь не доказывает отсутствие событий.','Current synthetic walkthrough log for this employee. Historical sign-ins and actions are not loaded; their absence here does not prove no events occurred.'];}else if(a==='recovery'){const rec=s.records[management.staff];if(!rec?.blocked)return false;rec.recovery=true;}else return false;return true;}
const managementPageBeforeSecurity=managementPage;
managementPage=function(){return managementAccess().read&&staffSecurity().open?heading(mn('Сотрудники и права','Staff and access'),mn('Защита учётных записей','Account protection'))+'<div class="management-workspace security-workspace">'+securityPage()+'</div>':managementPageBeforeSecurity();};
const managementDetailBeforeSecurity=managementStaffDetail;
managementStaffDetail=function(){return managementDetailBeforeSecurity().replace('</h2>','</h2>'+securityButton('Защита аккаунта','Account protection','open'));};
const managementChangeBeforeSecurity=managementCanChange;
managementCanChange=function(id){return management.assignments[id]?.status!=='blocked'&&managementChangeBeforeSecurity(id);};
function securityIncidentPage(x){management.staff=x.staffSecurity;const op=x.securityOperation,blocked=op?.status==='confirmed'&&op.applied;return securityButton('К защите аккаунта','Back to account protection','return')+heading(mn(...x.title))+`<div class="management-workspace"><p>${x.id} · ${x.staffSecurity}</p><section class="panel"><h2>${mn('Что подтверждено','Confirmed facts')}</h2><p>${blocked?mn('Блокировка аккаунта подтверждена.','Account blocking is confirmed.'):mn('Блокировка ещё не подтверждена.','Account blocking is not yet confirmed.')}</p><p>${escape(op?.id||'')} · ${managementStatus(op?.status||'unknown')}</p><p>${escape(op?.payload.staff===x.staffSecurity?op.payload.reason:'')}</p>${blocked?securityEffects(true):securityButton('Проверить команду в карточке','Check command in account','return')}<p>${mn('Доставка уведомлений двум владельцам не подтверждена.','Notification delivery to both owners is unconfirmed.')}</p></section><section class="panel"><h2>${mn('Разбор и восстановление','Investigation and recovery')}</h2><p>${mn('Нужно проверить последние действия сотрудника и исключить последствия взлома. Блокировка сама по себе не устраняет причину инцидента.','Review recent employee actions and assess compromise effects. Blocking alone does not resolve the incident cause.')}</p>${securityButton('Проверить последние действия','Review recent actions','audit')}${securityRecoveryText()}<p class="muted">${mn('Учебный разбор остаётся открытым. Доказательства устранения причины и защищённое восстановление — следующий отдельный этап.','The synthetic investigation stays open. Resolution evidence and protected recovery are a separate next step.')}</p></section></div>`;}
const incidentDetailBeforeSecurity=incidentDetail;
incidentDetail=function(){const x=incidentCurrent();return x?.staffSecurity?securityIncidentPage(x):incidentDetailBeforeSecurity();};
document.addEventListener('click',e=>{const b=e.target.closest('[data-security]');if(b&&!b.disabled){securityAction(b.dataset.security);render();}});
document.addEventListener('input',e=>{if(e.target.id==='security-reason'){const s=staffSecurity(),refresh=!!(s.review||s.proof),start=e.target.selectionStart,end=e.target.selectionEnd;s.reason=e.target.value;s.review=null;s.proof=null;if(refresh){render();const input=document.querySelector('#security-reason');input?.focus();input?.setSelectionRange(start,end);}}});
document.addEventListener('change',e=>{const s=staffSecurity();if(e.target.id==='security-outcome')s.outcome=e.target.value;else if(e.target.id==='security-auth'){s.auth=e.target.value;s.proof=null;}else return;render();});
